const cfg = $('Config').first().json;
const event = $('Backup Event').first().json.body ?? $('Backup Event').first().json;
const completedAt = new Date(event.completed_at);
const ageMinutes = Number.isNaN(completedAt.valueOf()) ? Infinity : (Date.now() - completedAt.valueOf()) / 60000;
const size = Number(event.size_bytes || 0);
const checksumOk = event.checksum_ok === true;
const restoreTestOk = event.restore_test_ok === true;
const valid = event.status === 'success' && size >= Number(cfg.minimum_bytes) && ageMinutes <= Number(cfg.maximum_age_minutes) && checksumOk && restoreTestOk;
const failures = [];
if (event.status !== 'success') failures.push('backup status is not success');
if (size < Number(cfg.minimum_bytes)) failures.push('backup is unexpectedly small');
if (ageMinutes > Number(cfg.maximum_age_minutes)) failures.push('backup is stale or missing a valid timestamp');
if (!checksumOk) failures.push('checksum was not verified');
if (!restoreTestOk) failures.push('restore test did not pass');
return [{ json: { database: event.database || 'unknown', valid, size_bytes: size, completed_at: event.completed_at || null, failures, content: valid ? '' : `🚨 PostgreSQL backup verification failed for **${event.database || 'unknown'}**: ${failures.join('; ')}.` } }];
